/* Editorial revision only: existing products, task IDs, marks and workload stay intact. */
(()=>{'use strict';
const conditions={seminovo:'seminovo',lacrado:'lacrado',novo:'novo',pendente:'com cadastro pendente'};
function profile(p){const n=p.name||'',m=n.match(/iPhone\s+(\d+)\s*(Pro Max|Pro|Plus|Mini)?/i);return {iphone:!!m,generation:m?Number(m[1]):null,tier:m?(m[2]||'normal').toLowerCase():null,base:n.replace(/\b\d+\s*GB\b/gi,'').replace(/\s+/g,' ').trim().toLowerCase(),capacity:n.match(/\b(\d+)\s*GB\b/i)?.[1]||null}}
function classify(a,b){const x=profile(a),y=profile(b);if(a.id===b.id)return 'single';if(a.condition!==b.condition)return 'condition';if(x.base===y.base&&x.capacity!==y.capacity)return 'storage';if(x.iphone&&y.iphone){if(x.generation===y.generation&&new Set([x.tier,y.tier]).size===2&&[x.tier,y.tier].every(t=>t==='pro'||t==='pro max'))return 'size';if(Math.abs(x.generation-y.generation)<=1&&x.tier===y.tier)return 'peer'}return 'needs'}
const fixes={
 '2026-11-17':['Dois perfis de compra de iPhone seminovo','Apresentar as unidades por proposta de uso, condição e investimento'],
 '2026-12-03':['Duas opções lacradas para conhecer','Conferir geração, armazenamento e valor das opções lacradas'],
 '2026-12-07':['Presentes para diferentes orçamentos','Apresentar opções com valores confirmados no dia']
};
for(const d of DAYS)if(fixes[d.date]){[d.focus,d.angle]=fixes[d.date]}
function context(day){const a=productFor(day,0),b=productFor(day,1);return {a,b,mode:classify(a,b)}}
function poll(c){
 const suffix=' Retomamos as dúvidas no próximo dia de atendimento.';
 if(c.mode==='storage')return {title:'Enquete — quanto espaço você usa?',options:['Uso mais leve','Muitas fotos e vídeos'],script:'Pensando em armazenamento, como é seu uso: poucos aplicativos e arquivos ou muitas fotos e vídeos?'+suffix,shot:'Mostre as capacidades reais de '+c.a.name+' e '+c.b.name+'. Explique o espaço para arquivos; não atribua mais velocidade só por ter mais GB.'};
 if(c.mode==='size')return {title:'Enquete — qual tamanho funciona para você?',options:['Mais compacto','Tela maior'],script:'Na sua rotina, o que você prefere: um aparelho mais compacto na mão ou uma tela maior?'+suffix,shot:'Mostre '+c.a.name+' e '+c.b.name+' na mão, à mesma distância. Identifique também o armazenamento e a condição de cada unidade; o critério desta enquete é tamanho.'};
 if(c.mode==='condition')return {title:'Enquete — qual condição você procura?',options:[conditions[c.a.condition]||'Primeira condição',conditions[c.b.condition]||'Segunda condição'],script:'Entre essas condições de compra, qual você quer conhecer melhor? Vamos conferir o estado, o que acompanha e os valores de cada unidade.'+suffix,shot:'Identifique '+c.a.name+' ('+(conditions[c.a.condition]||c.a.condition)+') e '+c.b.name+' ('+(conditions[c.b.condition]||c.b.condition)+'). Mostre cada proposta com seus dados; confirme bateria e conservação quando seminovo e embalagem quando lacrado.'};
 if(c.mode==='peer'||c.mode==='single')return {title:'Enquete — qual detalhe mostrar melhor?',options:['Câmera em uso','Condição e bateria'],script:'Qual detalhe dessas opções você quer ver melhor: a câmera funcionando ou a condição e a bateria da unidade?'+suffix,shot:'Use '+c.a.name+(c.mode==='single'?'':' e '+c.b.name)+'. Para câmera, use a mesma cena e iluminação; para bateria, informe o dado real da unidade sem prometer duração.'};
 return {title:'Enquete — o que pesa na sua escolha?',options:['Valor da compra','Recursos que uso'],script:'Hoje mostramos opções para necessidades diferentes. O que pesa mais na sua escolha: o valor da compra ou os recursos que você vai usar?'+suffix,shot:'Apresente '+c.a.name+' e '+c.b.name+' separadamente, com modelo, armazenamento e condição. A enquete identifica a prioridade do cliente; os aparelhos não são tratados como concorrentes da mesma categoria.'};
}
const beforeStory=mkStory;
mkStory=function(day,slot,index){const task=beforeStory(day,slot,index),type=slot[1];if(day.sunday||day.holiday||task.ownerOnly)return task;const c=context(day);
 if(type==='interacao'){const p=poll(c);task.name=p.title;task.shot=p.shot+' Use enquete nativa do Instagram: “'+p.options.join('” / “')+'”.';task.script=p.script;task.cta='Vote na enquete.';task.why='Descobrir a necessidade do cliente e preparar uma demonstração útil para o próximo expediente.';task.pollOptions=p.options;task.editorialMode=c.mode;return task}
 if(type==='saudacao'&&!task.who.startsWith('Thiago')){task.shot='Um Story curto com a pessoa responsável aparecendo e apresentando o tema do dia. Use uma frase de abertura e uma imagem real da loja.';if(day.date==='2026-11-17'){task.script='Bom dia! Hoje temos dois iPhones seminovos com propostas diferentes. Vou mostrar cada unidade e as condições reais para você avaliar o que combina com seu uso e seu orçamento.';task.cta='Acompanhe os detalhes nos próximos Stories.'}}
 if(/^produto[2-4]?$/.test(type)){const p=productFor(day,task.productIndex);if(p.condition==='pendente')return task;const topic=String(day.focus+' '+day.angle).toLowerCase();let detail='Vou mostrar a unidade, o armazenamento e a condição real para você avaliar com calma.';
 if(/câmera|câmeras|foto|vídeo/.test(topic)){detail=p.condition==='lacrado'?'Vou mostrar a caixa e os dados conferidos desta opção. Para uma demonstração, usamos somente unidade autorizada de exposição.':'Vou mostrar uma foto ou vídeo feito agora com esta unidade. Em uma comparação, usamos a mesma cena e iluminação.'}
 else if(/armazenamento|256.*512|espaço/.test(topic))detail='Vamos conferir a capacidade desta opção e conversar sobre quanto espaço você usa com fotos, vídeos e aplicativos.';
 else if(/tamanho|compacto|pro max/.test(topic))detail=p.condition==='lacrado'?'Vou mostrar a embalagem e as informações confirmadas do modelo.':'Vou mostrar o tamanho na mão e o formato desta unidade, sem mudar a distância da câmera.';
 else if(/bateria|segura|condição|sem esconder|unidade/.test(topic))detail='Vou mostrar a conservação e os dados reais desta unidade. Bateria e garantia só entram depois de conferidas.';
 task.script=(type==='produto2'&&c.mode==='needs'?'Agora, outra proposta para você avaliar: ':'Esta é a opção de hoje: ')+p.name+'. '+detail;
 const care=p.condition==='lacrado'?'Mostre a caixa lacrada e as informações confirmadas, sem abrir nem revelar serial.':p.condition==='seminovo'?'Mostre conservação e bateria real da unidade, sem dados pessoais e sem prometer autonomia.':'Mostre o aparelho real e um recurso conferido, sem dados pessoais.';task.shot=(task.count>1?'Story 1: demonstração do tema, em 8–12 segundos. Story 2: condição, armazenamento e valor confirmado; a chamada para conversar fica neste segundo Story. ':'Um Story de 8–12 segundos com uma demonstração objetiva. ')+care;
 task.cta='Quer ver os detalhes desta unidade e o valor atualizado? Chama no direct.';
 task.disclaimer='Confirme modelo, condição, bateria quando aplicável, garantia, valor e disponibilidade antes de publicar. Condição Black somente se aprovada e dentro do prazo.';
 }
 if(type==='acessorio'&&task.count===1){task.shot='Um único Story: mostre um uso ou encaixe real do acessório e identifique o modelo compatível, depois de conferir. Não acrescente um segundo Story obrigatório.';task.script='Esse acessório pode fazer parte da sua rotina. Vou mostrar um uso real e conferir a compatibilidade com o modelo certo.';task.cta='Quer conferir se serve no seu aparelho? Manda o modelo no direct.'}
 if(type==='fecho'&&!['2026-11-30','2026-12-31'].includes(day.date)){task.name='Resumo dos destaques de hoje';task.shot='Um Story com os dois destaques já apresentados, sem acrescentar novos aparelhos ou prometer atendimento fora do expediente.';task.script='Esses foram os destaques de hoje na Zicão Store. A equipe confirma os detalhes da unidade, a disponibilidade e o valor atualizado no atendimento.';task.cta='Quer conferir uma das opções? Chama no WhatsApp.'}
 return task;
};
const beforeMedia=mediaTask;
mediaTask=function(day,type){const task=beforeMedia(day,type);if(type!=='feed'||day.sunday||day.holiday)return task;const c=context(day),p=poll(c),condition=c.a.condition===c.b.condition?({seminovo:'As duas opções são seminovas',lacrado:'As duas opções são lacradas',novo:'As duas opções são novas'}[c.a.condition]||'Condição confirmada em cada unidade'):'As condições são diferentes e estão identificadas em cada opção';
 task.name='Post de feed — '+day.focus;if(c.mode==='single'){task.shot='Fotos reais de '+c.a.name+': apresentação, condição e detalhes confirmados, seguida de uma chamada para conversar.';task.script='Conheça esta unidade: '+c.a.name+'. Confira o estado e os detalhes do aparelho. Quer saber o valor atualizado e a disponibilidade? Chama a Zicão Store.';task.cta='Uma chamada para conferir as condições reais.';return task}
 task.shot=(c.mode==='needs'?'Carrossel por perfil de compra: apresentação, primeira proposta, segunda proposta e uma chamada para conversar.':'Carrossel com critério claro: '+p.title.replace('Enquete — ','')+'.')+' Fotos reais de '+c.a.name+' e '+c.b.name+'. Em cada imagem, identifique modelo, armazenamento e condição, com valores confirmados. '+(c.mode==='needs'?'Explique o que cada opção oferece ao uso do cliente.':'Use o mesmo critério nas duas unidades.');
 task.script='Hoje separamos '+c.a.name+' e '+c.b.name+' para você conhecer. '+condition+'. Confira os detalhes de cada unidade e escolha pensando no seu uso e no seu orçamento. Quer conferir os valores atuais e a disponibilidade? Chama a Zicão Store.';
 task.cta='Uma chamada para conversar e conferir as condições reais.';task.disclaimer='Não chamar de lacrado um seminovo, nem apresentar opções de categorias diferentes como uma disputa de desempenho. Garantia, bateria e preço precisam ser confirmados.';return task;
};
window.StudioScriptQuality={classify,context,poll,fixes};
if(typeof renderDay==='function')renderDay();
})();
